    if (!o.bare) s += shadowOf(home) + pathAll(sc, home, so);
    if (o.marks) SLOT_ORDER.forEach(function(k){ if (!yard[k] && !(k === "corner" && yard.side && YARD[yard.side].wide)) s += emptySlot(k); });

