    for (var sp = 0; sp < 2; sp++) for (var i = 1; i <= 4; i++){ var t = i / 5, a = tops[sp], b = tops[sp + 1]; out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t + Math.sin(t * Math.PI) * 4 + 1.8, BULBS[k++ % BULBS.length]]); }
