      bits: function(){ var c = P(1.8, 1.8, 2.15), s = ""; [[-10, 2], [-7, -6], [-2, 4], [1, -10], [5, -2], [9, 4], [11, -6], [-4, -2], [3, 8], [-9, 9], [7, -11], [-1, -6]].forEach(function(q, i){ s += circ(c[0] + q[0], c[1] + q[1] + 2, i % 2 ? 1.5 : 1.1, "#FFFFFF", .5); }); return s; }
