        feet.forEach(function(q, i){ var t = rb.tops[i]; s += L(T.seg(q, t), 3.2) + L(T.seg(q, t), 1.5, K.wood) + ell(q[0], q[1], 3.4, 1.5, "#FFFFFF", .8) + FO("M" + f(t[0] - 2.4) + " " + f(t[1] + .6) + " q2.4 -4.4 4.8 0 z", "#FFFFFF", .8); });
