  var zig = (function(){ var d = ""; for (var i = 0; i <= 12; i++){ var x = 64 + i * 6, t = (x - 48) / 104, y = 107 + 2 * t * (1 - t) * 44 + (i % 2 ? 7.4 : 2.8); d += (i ? " L" : "M") + f(x) + " " + f(y); } return d; })();
